CREATE TABLE bulk_import_job (id INTEGER PRIMARY KEY,target_type TEXT NOT NULL CHECK(target_type IN ('OUTLET','IP_RANGE','IP_POOL')),file_format TEXT NOT NULL CHECK(file_format IN ('CSV','XLSX')),original_file_name TEXT NOT NULL CHECK(length(original_file_name) BETWEEN 1 AND 255),file_sha256 TEXT NOT NULL CHECK(length(file_sha256)=64),status TEXT NOT NULL CHECK(status IN ('VALIDATING','PREVIEW_READY','COMPLETED','FAILED','CANCELLED','EXPIRED')),total_rows INTEGER NOT NULL DEFAULT 0 CHECK(total_rows>=0),valid_rows INTEGER NOT NULL DEFAULT 0 CHECK(valid_rows>=0),error_rows INTEGER NOT NULL DEFAULT 0 CHECK(error_rows>=0),created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),confirmed_at TEXT,completed_at TEXT,FOREIGN KEY(created_by) REFERENCES sys_user(id) ON DELETE RESTRICT);
CREATE INDEX idx_bulk_import_job_creator_time ON bulk_import_job(created_by,created_at);
CREATE TABLE bulk_import_error (id INTEGER PRIMARY KEY,job_id INTEGER NOT NULL,row_number INTEGER NOT NULL CHECK(row_number>=1),field_name TEXT CHECK(field_name IS NULL OR length(field_name)<=64),error_code TEXT NOT NULL CHECK(length(error_code) BETWEEN 1 AND 64),error_message TEXT NOT NULL CHECK(length(error_message) BETWEEN 1 AND 500),FOREIGN KEY(job_id) REFERENCES bulk_import_job(id) ON DELETE CASCADE);
CREATE INDEX idx_bulk_import_error_job_row ON bulk_import_error(job_id,row_number);
CREATE TABLE ip_application (id INTEGER PRIMARY KEY,applicant_user_id INTEGER NOT NULL,applicant_name TEXT NOT NULL CHECK(length(applicant_name) BETWEEN 1 AND 100),unified_auth_id TEXT NOT NULL CHECK(length(unified_auth_id) BETWEEN 1 AND 64),branch_id INTEGER NOT NULL,outlet_id INTEGER NOT NULL,asset_type TEXT NOT NULL CHECK(asset_type IN ('TECH','NON_TECH')),asset_code TEXT,device_type TEXT CHECK(device_type IN ('PC','OTHER')),status TEXT NOT NULL CHECK(status IN ('PENDING','APPROVED','REJECTED')),rejection_reason TEXT,reviewed_by INTEGER,reviewed_at TEXT,version INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),FOREIGN KEY(applicant_user_id) REFERENCES sys_user(id) ON DELETE RESTRICT,FOREIGN KEY(branch_id) REFERENCES branch(id) ON DELETE RESTRICT,FOREIGN KEY(outlet_id) REFERENCES outlet(id) ON DELETE RESTRICT,FOREIGN KEY(reviewed_by) REFERENCES sys_user(id) ON DELETE RESTRICT,CHECK((asset_type='TECH' AND asset_code IS NOT NULL AND device_type IS NOT NULL) OR (asset_type='NON_TECH' AND asset_code IS NULL AND device_type IS NULL)),CHECK((status='REJECTED' AND rejection_reason IS NOT NULL) OR status<>'REJECTED'));
CREATE INDEX idx_ip_application_owner_time ON ip_application(applicant_user_id,created_at);
CREATE INDEX idx_ip_application_pending ON ip_application(status,branch_id,created_at) WHERE status='PENDING';
CREATE TABLE ip_assignment (id INTEGER PRIMARY KEY,application_id INTEGER NOT NULL UNIQUE,ip_pool_id INTEGER NOT NULL,resource_code TEXT,assigned_by INTEGER NOT NULL,assigned_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),FOREIGN KEY(application_id) REFERENCES ip_application(id) ON DELETE RESTRICT,FOREIGN KEY(ip_pool_id) REFERENCES ip_address_pool(id) ON DELETE RESTRICT,FOREIGN KEY(assigned_by) REFERENCES sys_user(id) ON DELETE RESTRICT);
CREATE UNIQUE INDEX uk_ip_assignment_pool ON ip_assignment(ip_pool_id);
CREATE UNIQUE INDEX uk_ip_assignment_resource_code ON ip_assignment(resource_code) WHERE resource_code IS NOT NULL;
CREATE TABLE user_notification (id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL,application_id INTEGER NOT NULL,message TEXT NOT NULL CHECK(length(message) BETWEEN 1 AND 500),is_read INTEGER NOT NULL DEFAULT 0 CHECK(is_read IN (0,1)),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),FOREIGN KEY(user_id) REFERENCES sys_user(id) ON DELETE RESTRICT,FOREIGN KEY(application_id) REFERENCES ip_application(id) ON DELETE RESTRICT);
CREATE INDEX idx_user_notification_user_time ON user_notification(user_id,created_at);
